import {newPlayState} from './board-model.js';import {validateTheme} from './theme-model.js';import {validateComposition} from './presentation-model.js';
export function makeBackup(board,play,at=new Date().toISOString()){return {format:'dmb-private-board-play-v1',boardId:board.id,sourcePin:board.pin,savedAt:at,play:structuredClone(play)}}
export function reviewBackup(text,board){if(typeof text!=='string'||text.length>5_000_000)throw Error('Backup exceeds 5 MB');const b=JSON.parse(text);if(b.format!=='dmb-private-board-play-v1'||b.boardId!==board.id)throw Error('Backup belongs to another adventure or unsupported format');if(b.sourcePin!==board.pin&&!board.previousPins?.includes(b.sourcePin))throw Error('Source revision is not available here');const state=b.play;if(!state||typeof state!=='object'||Array.isArray(state)||typeof state.notes!=='string'||!Array.isArray(state.decisions))throw Error('Invalid session writing');for(const name of ['sceneNotes','entityNotes','completed','selected','other'])if(!state[name]||typeof state[name]!=='object'||Array.isArray(state[name]))throw Error('Invalid '+name);for(const name of ['sceneNotes','entityNotes','other','edits'])for(const value of Object.values(state[name]??{}))if(typeof value!=='string')throw Error('Invalid writing field');for(const value of Object.values(state.completed))if(typeof value!=='boolean')throw Error('Invalid completion mark');for(const value of Object.values(state.selected))if(!Array.isArray(value)||value.some(id=>typeof id!=='string'))throw Error('Invalid selected choices');for(const d of state.decisions)if(!d||typeof d.card!=='string'||!Array.isArray(d.choices)||d.choices.some(id=>typeof id!=='string')||typeof d.note!=='string')throw Error('Invalid decision record');for(const name of ['edits','compositions','compositionDrafts'])if(state[name]&&(typeof state[name]!=='object'||Array.isArray(state[name])))throw Error('Invalid '+name);if(state.presentationHistory&&!Array.isArray(state.presentationHistory))throw Error('Invalid presentation history');if(state.theme)validateTheme(state.theme);if(b.sourcePin===board.pin)for(const name of ['compositions','compositionDrafts'])for(const blocks of Object.values(state[name]??{}))validateComposition(blocks,board);const ids=new Set(board.cards.map(c=>c.id));const orphaned=[...new Set([...Object.keys(state.sceneNotes),...Object.keys(state.other),...Object.keys(state.completed),...state.decisions.map(d=>d.card)].filter(id=>!ids.has(id)))];return {backup:b,previousRevision:b.sourcePin!==board.pin,orphaned,summary:{notes:state.notes.length,sceneNotes:Object.values(state.sceneNotes).filter(Boolean).length,decisions:state.decisions.length,compositions:Object.keys(state.compositions??{}).length}}}
export function restoredState(review,board){if(review.previousRevision)throw Error('Previous revision must restore under its original source key');const result={...newPlayState(),...structuredClone(review.backup.play)};if(!board.cards.some(c=>c.id===result.current))result.current=board.startCard??board.cards[0].id;if(!['plan','play'].includes(result.mode))result.mode='plan';if(!['cards','document'].includes(result.view))result.view='cards';return result}
